properties.query:
let detectionWindow = 1h;   // must equal queryFrequency
let baseline = 14d;         // must stay <= queryPeriod
// TUNING 1 of 2: the event name must name a privileged object AND end in a grant-type verb.
// Bare 'member', 'assign', 'owner' and 'group' are deliberately absent - they match
// routine directory user and group activity.
let escalationObjects = @"(?i)role|permission|privilege|admin|rights|entitlement|elevat|justintime";
let grantVerbs = @"(?i)(Added|Assigned|Granted|Elevated|Approved|Created|Updated|Modified|Changed)$";
// TUNING 2 of 2: tenant specific exclusions, filled in at deployment time. Exact match,
// case insensitive. Leave empty if unused.
let excludedEventNames = dynamic([]);
//   e.g. dynamic(["Delinea.Vault.Group.Updated"]);
let excludedServiceTypes = dynamic([]);
//   e.g. dynamic(["Identity"]);
let excludedActors = dynamic([]);
//   e.g. dynamic(["svc-directory-sync"]);
let grants =
    DelineaAuditEvents_CL
    | where TimeGenerated > ago(baseline)
    | extend IngestedAt = ingestion_time()
    | extend d = parse_json(RawData)
    | extend EventName = tostring(coalesce(d.eventType.name, d.eventType.internalName))
    | where EventName matches regex escalationObjects and EventName matches regex grantVerbs
    | extend Actor = tostring(coalesce(d.actor.name, d.actor.email, d.actor.displayName)),
             ServiceType = tostring(d.service.type),
             Target = tostring(coalesce(d.target.displayName, d.target.name)),
             // ID first - display names can change. Empty when the event carries no target.
             TargetKey = tostring(coalesce(d.target.id, d.target.platformId, d.target.name, d.target.displayName)),
             FieldChanges = tostring(d.fieldChanges),
             RawSrcIP = tostring(d.source.host.network.ipAddress)
    | where isnotempty(Actor)
    | where not(EventName in~ (excludedEventNames))
        and not(ServiceType in~ (excludedServiceTypes))
        and not(Actor in~ (excludedActors))
    // '0.0.0.0' is the placeholder reported for events that have no network origin.
    | extend SrcIP = iff(RawSrcIP in ("", "0.0.0.0"), "", RawSrcIP);
// Batch by ingestion time so a late arriving event is still evaluated exactly once.
// The baseline is keyed on the target too, so repeating a grant on the same target is
// suppressed but the same grant against a new target still alerts.
let priorGrants = grants | where IngestedAt <= ago(detectionWindow) | distinct Actor, EventName, TargetKey;
grants
| where IngestedAt > ago(detectionWindow)
| join kind=leftanti priorGrants on Actor, EventName, TargetKey
| summarize Changes = count(), EventNames = make_set(EventName, 20),
            Targets = make_set_if(Target, isnotempty(Target), 20),
            FieldChanges = make_list_if(FieldChanges, isnotempty(FieldChanges), 10),
            SourceIPs = make_set_if(SrcIP, isnotempty(SrcIP), 20),
            SrcIP = take_anyif(SrcIP, isnotempty(SrcIP)),
            StartTime = min(TimeGenerated), EndTime = max(TimeGenerated) by Actor
| project StartTime, EndTime, Actor, Changes, EventNames, Targets, FieldChanges, SourceIPs, SrcIP
| sort by StartTime desc
